function nichePrompt(){return `Помоги подобрать поисковые запросы для поиска конкурентов и идей контента в Instagram.
Моя ниша: [ниша]. Продукт или услуга: [что предлагаю].
Аудитория: [для кого]. География: [город, район или онлайн]. Язык: [язык].
Составь 15–20 коротких запросов: названия ниши, профессии, продукты, услуги и смежные темы. Для локального бизнеса добавь сочетания с городом и районом. Используй слова, которые могут встречаться в названиях и описаниях профилей. Раздели запросы на группы и выбери 5 для начала. Не выдумывай аккаунты и результаты поиска.`}
function m2Cards(items){return '<div class="m2-cards">'+items.map(([n,t,d])=>`<div class="m2-card"><span class="m2-index">${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')+'</div>'}
function resetShot(file,title,caption,top,height){return `<figure class="m2-shot"><figcaption><b>${title}</b><p>${caption}</p></figcaption><button class="m2-screen" data-image="assets/${file}" aria-label="Увеличить: ${title}"><img src="assets/${file}" alt="${title}" loading="lazy" width="1320" height="2868"><span class="m2-highlight" style="top:${top}%;height:${height}%" aria-hidden="true"></span></button></figure>`}
function moduleTwoReset(){return `<details class="m2-reset"><summary>Нужные ролики не появляются: сброс рекомендаций</summary><div class="m2-reset-body"><p>Если лента не помогает искать идеи, я могу настроить её заново. Сброс нельзя отменить. Данные аккаунта не удаляются; рекомендации снова подстраиваются под взаимодействия.</p><div class="m2-shots">${resetShot('reset-menu.png','1. Настройки контента','В «Настройках и действиях» нахожу раздел «Что вы видите».',52.5,5.3)}${resetShot('reset-content.png','2. Сбросить рекомендуемый контент','Открываю этот пункт. Блокировка на 30 дней - отдельная функция.',48.5,4.5)}${resetShot('reset-explanation.png','3. Условия и кнопка «Далее»','Читаю условия и следую подсказкам Instagram, если решил выполнить сброс.',90,5)}</div><p class="note">После сброса возвращаюсь к подборке из 188 роликов, смотрю подходящие примеры, лайкаю и комментирую по делу.</p><details><summary>Остальные настройки на скриншоте</summary><ul><li><b>Потенциально неприемлемый контент / Политический контент</b> - предпочтения показа этих категорий. Внутренние значения здесь не видны.</li><li><b>Интересует / Не интересует</b> - разделы для работы с сигналами о предпочтениях.</li><li><b>Особые слова и фразы</b> - фильтрация рекомендаций по словам; содержимое списка на снимке не показано.</li><li><b>Заблокировать рекомендуемые публикации</b> - у меня выключено. Иначе рекомендации в ленте скрываются на 30 дней, а они нужны для поиска.</li><li><b>Скрыть всплывающие сообщения о действиях</b> - у меня выключено. Это отображение значков действий, а не сброс рекомендаций.</li></ul></details></div></details>`}
const chapterTwoChecks=[['m2_hook','Отметь, что скриншот хука сохранён.'],['m2_video','Отметь, что видео сохранено.'],['m2_caption','Отметь, что описание скопировано.']];
function optionalAnswer(i){return i===9||i===10}
function moduleTwoSummary(){const f=state.fields,row=(t,v)=>`<div class="m2-card"><h3>${t}</h3><p>${v}</p></div>`,txt=(k,empty)=>String(f[k]||'').trim()?esc(String(f[k]).trim()):`<span class="m2-empty">${empty}</span>`,mark=k=>f[k]?'Готово':'<span class="m2-empty">Не отмечено</span>';return block('Итог главы: мой комплект',`<div class="m2-cards m2-summary">${row('Референс',txt('answer_7','Ссылка не сохранена. Вернись к миссии «Отбери сильный референс».'))}${row('Конкурент',txt('answer_8','Не записан. Это необязательно для комплекта.'))}${row('Скриншот хука',mark('m2_hook'))}${row('Видео',mark('m2_video'))}${row('Описание',mark('m2_caption'))}</div><p class="note">Всё готово - переходи к третьему модулю «Тексты с ИИ».</p>`)}
function moduleTwoTools(i){
if(i===6)return `<section class="m2-lab"><span class="tiny">МОЙ МАРШРУТ · 01</span><h2>От подборки к своей ленте</h2>${m2Cards([['01','188 примеров','Открываю готовую подборку Reels.'],['02','Живой интерес','Смотрю, лайкаю и комментирую по делу.'],['03','Новые находки','Замечаю похожие ролики в рекомендациях.']])}<a class="primary" href="references.html">Открыть 188 Reels ${icon('chevron')}</a></section>${moduleTwoReset()}${block('Как взаимодействия меняют рекомендации','<p>Meta объясняет: рекомендации персонализируются со временем на основе контента и аккаунтов, с которыми человек взаимодействует.</p><p><a href="https://about.fb.com/news/2024/11/introducing-recommendations-reset-instagram/" target="_blank" rel="noopener">Объяснение персонализации от Meta</a></p>')}`;
if(i===7)return block('Мой фильтр отбора',`<div class="m2-thresholds"><div><span class="tiny">ДО 10 ДНЕЙ</span><h3>100 лайков <em>или</em> 10 репостов</h3></div><div><span class="tiny">СТАРШЕ ПОЛУГОДА</span><h3>5 000 лайков <em>или</em> 1 000 репостов</h3></div></div><p>Порядок проверки: 1) возраст ролика, 2) лайки или репосты. Достаточно одного показателя. Ролик от 10 дней до полугода пропускаю.</p>${m2Cards([['А','6 дней · 140 лайков','Подходит по лайкам, даже если репостов меньше 10.'],['Б','8 месяцев · 1 200 репостов','Подходит по репостам. 5 000 лайков не обязательны.'],['В','7 дней · 60 лайков · 4 репоста','При скрытых просмотрах пока не подходит. Ищу другой.']])}<details><summary>Дополнительно: просмотры видны</summary>${select('refAge','Возраст ролика',['До 10 дней','Старше полугода','От 10 дней до полугода'])}${field('refFollowers','Подписчиков у автора','10000','number')}${field('refViews','Просмотров у ролика','18000','number')}<p id="refResult" role="status"></p><p class="note">Свежий ролик: не менее 1,8 × подписчиков. Старый: от 2 млн просмотров, подписчики не важны.</p></details>`);
if(i===8)return `<section class="m2-lab"><span class="tiny">УЧЕБНАЯ СХЕМА · НЕ СКРИНШОТ INSTAGRAM</span><h2>От запроса к конкуренту</h2><div class="m2-search"><span>Поиск</span><b>торты Брест</b></div><div class="m2-profile"><div class="m2-avatar">К</div><div><b>Кондитер · торты на заказ</b><p>Брест · примеры работ · авторские десерты</p></div></div>${m2Cards([['01','Открываю профиль','Смотрю тему и публикации.'],['02','Выбираю действие','Подписываюсь или взаимодействую с интересными роликами.']])}</section>${block('Промпт для ключевых слов',`<p>Заполни скобки и отправь в ChatGPT.</p><pre class="prompt-text">${esc(nichePrompt())}</pre><button class="secondary" data-copy-niche>Скопировать промпт</button>`)}`;
if(i===9)return `<section class="m2-lab"><span class="tiny">УЧЕБНЫЙ ПРИМЕР</span><h2>Сохраняю именно хук</h2><div class="m2-reel"><span>ТЕКСТ НА ВИДЕО</span><div class="m2-hook">ТРИ ОШИБКИ,<br>ИЗ-ЗА КОТОРЫХ<br>ТВОЙ ТОРТ ОСЕДАЕТ</div><span>Весь текст должен читаться на скриншоте</span></div><p>Снимок остаётся в галерее. Ссылку на GPT для триггеров дам в третьем модуле.</p></section>`;
if(i===10)return `<section class="m2-lab"><span class="tiny">ВИДЕО → ГАЛЕРЕЯ → ЗВУК В EDITS</span><h2>Отправляю ссылку в @SaveAsBot</h2><div class="m2-chat"><div>Ссылка на выбранный Reel</div><div><b>@SaveAsBot</b><p>Видеофайл → сохранить в галерею</p></div></div><p class="note">Схема процесса. Ответ бота может выглядеть иначе.</p><a class="primary" href="https://t.me/SaveAsBot" target="_blank" rel="noopener">Открыть SaveAsBot ${icon('chevron')}</a></section>${detail('Бот ничего не прислал','Жду и пробую позже: возможен временный сбой.')}${detail('Бот пишет, что скачать нельзя','Беру другой ролик: этот сейчас недоступен для скачивания через бота.')}`;
if(i===11)return `<section class="m2-lab"><span class="tiny">ФИНИШ МОДУЛЯ · ОДИН РЕФЕРЕНС</span><h2>Всё готово к переработке</h2>${m2Cards([['01','Скриншот хука','В галерее → в GPT для триггеров.'],['02','Видеофайл','В галерее → для извлечения звука в Edits.'],['03','Исходное описание','Текст → в отдельный чат для описаний.']])}${check('m2_hook','Скриншот хука сохранён и читается')}${check('m2_video','Видео сохранено и открывается')}${check('m2_caption','Описание скопировано в поле ниже')}<p class="note">Файлы остаются на телефоне. Здесь сохраняются ответы и отметки. Сначала проходим весь процесс на одном ролике, затем повторяем под свой план на день.</p></section>${moduleTwoSummary()}`;
return '';
}
